package com.fasterxml.jackson.databind.node;

import com.fasterxml.jackson.annotation.JsonAutoDetect;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializerProvider;
import com.fasterxml.jackson.databind.jsontype.TypeSerializer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class ObjectNode_equals_TriageGen2Test {

    private ObjectMapper mapper;
    private JsonNodeFactory factory;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
        factory = mapper.getFactory();
    }

    @Test
    public void testEquals_Reflexive() {
        ObjectNode node = factory.objectNode();
        node.put("key", "value");
        // if (o == this) return true;
        assertTrue("Node should be equal to itself", node.equals(node));
    }

    @Test
    public void testEquals_Null() {
        ObjectNode node = factory.objectNode();
        // if (o == null) return false;
        assertFalse("Node should not be equal to null", node.equals(null));
    }

    @Test
    public void testEquals_DifferentType() {
        ObjectNode node = factory.objectNode();
        ArrayNode arrayNode = factory.arrayNode();
        // if (o instanceof ObjectNode) ... return false;
        assertFalse("ObjectNode should not be equal to ArrayNode", node.equals(arrayNode));
        assertFalse("ObjectNode should not be equal to a String", node.equals("not a node"));
    }

    @Test
    public void testEquals_EqualNodes() {
        ObjectNode node1 = factory.objectNode();
        node1.put("a", 1);
        node1.put("b", "test");

        ObjectNode node2 = factory.objectNode();
        node2.put("a", 1);
        node2.put("b", "test");

        // _childrenEqual(ObjectNode) should return true
        assertTrue("Nodes with same content should be equal", node1.equals(node2));
    }

    @Test
    public void testEquals_DifferentContent() {
        ObjectNode node1 = factory.objectNode();
        node1.put("a", 1);

        ObjectNode node2 = factory.objectNode();
        node2.put("a", 2);

        assertFalse("Nodes with different values should not be equal", node1.equals(node2));
    }

    @Test
    public void testEquals_DifferentKeys() {
        ObjectNode node1 = factory.objectNode();
        node1.put("a", 1);

        ObjectNode node2 = factory.objectNode();
        node2.put("b", 1);

        assertFalse("Nodes with different keys should not be equal", node1.equals(node2));
    }

    @Test
    public void testEquals_EmptyNodes() {
        ObjectNode node1 = factory.objectNode();
        ObjectNode node2 = factory.objectNode();
        assertTrue("Two empty ObjectNodes should be equal", node1.equals(node2));
    }

    @Test
    public void testEquals_NestedObjects() {
        ObjectNode node1 = factory.objectNode();
        ObjectNode child1 = factory.objectNode();
        child1.put("inner", true);
        node1.set<JsonNode>("child", child1);

        ObjectNode node2 = factory.objectNode();
        ObjectNode child2 = factory.objectNode();
        child2.put("inner", true);
        node2.set<JsonNode>("child", child2);

        assertTrue("Nested ObjectNodes with same content should be equal", node1.equals(node2));

        child2.put("inner", false);
        assertFalse("Nested ObjectNodes with different content should not be equal", node1.equals(node2));
    }
}
